{v:'VER',what:'the HUD spec: the gun card stands at the right edge on the gear readout when the info panel above it leaves room, and steps left of the column only when the panel reaches its top',
 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__frame||typeof gunCardSpot!=='function'||!WEAPONS.dmr) return 'SKIP: no raid or gun card here';
   var bad=[], g, hudWas=P.hud, conWas=P.contracts, i, gc, p;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{ __pinDPR(1); }catch(_d){}
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     g.bagOpen=false; g.mapOpen=false; g.ents.length=0; keys={}; p=g.player;
     P.contracts=[]; P.hud=hudWas?JSON.parse(JSON.stringify(hudWas)):{}; delete P.hud.cond;
     for(i=0;i<3;i++){ g.gunCard={gk:'dmr',w:WEAPONS.dmr,vs:p.wep,route:'SLOT 2',t0:g.t||0}; __frame(0.016); }
     gc=GUNCARD_LAST;
     if(!gc||!(gc.w>0)) return 'SKIP: the gun card was not drawn';
     if(!HUDBOX.cond) return 'SKIP: no info panel here';
     if(gc.y<HUDBOX.cond.y+HUDBOX.cond.h) bad.push('the short panel test is not short (it ends at '+Math.round(HUDBOX.cond.y+HUDBOX.cond.h)+', the card starts at '+Math.round(gc.y)+')');
     else if(gc.x+gc.w<W-Math.round(LH(8))-2) bad.push('the gun card is not at the right edge though the panel above it is short (it ends at '+Math.round(gc.x+gc.w)+' of '+W+')');
     // a long panel pushes it left of the column
     P.hud.cond={dx:0,dy:Math.round(H*0.30),c:false};
     for(i=0;i<3;i++){ g.gunCard={gk:'dmr',w:WEAPONS.dmr,vs:p.wep,route:'SLOT 2',t0:g.t||0}; __frame(0.016); }
     gc=GUNCARD_LAST;
     if(HUDBOX.cond&&gc&&gc.y<HUDBOX.cond.y+HUDBOX.cond.h&&gc.x+gc.w>HUDBOX.cond.x) bad.push('the gun card is under the info panel when the panel is long');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ P.hud=hudWas; P.contracts=conWas; }catch(_r){} try{ var g2=__state(); if(g2){ g2.gunCard=null; if(!g2.over){ g2.player.downed=false; __endRaid('abandon'); } } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
